// @webkit-project
import { test, expect, type Page, type Browser } from '@playwright/test';
import { appendFileSync, readFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { unzipSync } from 'fflate';

/**
 * Audio splitter against real edge-case files. Every fixture is generated by tests/fixtures/make-audio-splitter-fixtures.sh
 * (ffmpeg) at test time, and each one either splits or ends with the named class for its real cause.
 * AS_FIXTURES picks the folder the files are written to (default: the system temp folder). AS_RECORD=<file> appends one JSON line
 * per run (class, parts, memory) so the same spec can be run on main and on a branch for a before/after table.
 */
const script = fileURLToPath(new URL('./fixtures/make-audio-splitter-fixtures.sh', import.meta.url));
const dir = process.env.AS_FIXTURES ?? join(tmpdir(), 'stayput-audio-splitter-fixtures');
const fx = (name: string) => join(dir, name);
const PHONE = 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Mobile Safari/537.36';

interface Outcome {
  state: 'ok' | 'error' | 'blocked';
  cls?: string;
  message: string;
  names: string[];
  sizes: number[];
  peakRssMb?: number;
  peakHeapMb?: number;
  ms: number;
}
type Ev = { n: string; d: Record<string, string> };

async function open(browser: Browser, userAgent?: string, before?: (page: Page) => Promise<void>) {
  const ctx = await browser.newContext({ userAgent, acceptDownloads: true, reducedMotion: 'reduce', serviceWorkers: 'block', baseURL: process.env.PW_BASE ?? 'http://localhost:4321' });
  const page = await ctx.newPage();
  await page.addInitScript(() => Object.defineProperty(Navigator.prototype, 'webdriver', { get: () => false }));
  await page.route('https://stats.keenankaufman.com/**', (route) =>
    route.fulfill({
      contentType: 'text/javascript',
      body: `window.umami={track:(n,d)=>{const k='__ev';const a=JSON.parse(sessionStorage.getItem(k)||'[]');a.push({n,d});sessionStorage.setItem(k,JSON.stringify(a));}};`,
    }),
  );
  await before?.(page);
  await page.goto('/tools/audio-splitter');
  await expect(page.locator('#tool')).toHaveAttribute('data-ready', 'true');
  return { page, close: () => ctx.close() };
}

const events = (page: Page): Promise<Ev[]> => page.evaluate(() => JSON.parse(sessionStorage.getItem('__ev') || '[]'));

interface Settings {
  times?: string;
  every?: { n: number; unit: 'seconds' | 'minutes' };
  format?: 'mp3' | 'wav';
}

/** Sizes of the renderer processes of this browser (Chromium only), in MB, and the page's JS heap. */
async function memory(page: Page, browser: Browser): Promise<{ rss: number; heap: number } | null> {
  if (browser.browserType().name() !== 'chromium') return null;
  try {
    const cdp = await page.context().newCDPSession(page);
    await cdp.send('Performance.enable');
    const heap = ((await cdp.send('Performance.getMetrics')).metrics.find((m) => m.name === 'JSHeapUsedSize')?.value ?? 0) / 1048576;
    const root = await browser.newBrowserCDPSession();
    const pids = (await root.send('SystemInfo.getProcessInfo')).processInfo.filter((p) => p.type === 'renderer').map((p) => p.id);
    await root.detach();
    await cdp.detach();
    const rows = execFileSync('ps', ['-o', 'pid=,rss=', '-p', pids.join(',')], { encoding: 'utf8' }).trim().split('\n');
    const rss = rows.reduce((n, r) => n + Number(r.trim().split(/\s+/)[1] ?? 0), 0) / 1024;
    return { rss, heap };
  } catch {
    return null;
  }
}

/** Drop the file in, apply the settings, press Run (when it can be pressed) and wait for the results or the error. */
async function splitFile(browser: Browser, file: string, settings: Settings = {}, opts: { userAgent?: string; measure?: boolean; breakOn?: (page: Page) => Promise<void> } = {}): Promise<Outcome> {
  const { page, close } = await open(browser, opts.userAgent, opts.breakOn);
  try {
    const started = Date.now();
    await page.locator('#file-input').setInputFiles(file);
    // The file is read once it is added: the info line says how long it is, or the error says it could not be read.
    await expect(page.locator('#sp-info:not(:empty), #error.is-active')).not.toHaveCount(0, { timeout: 600_000 });
    if (settings.format) await page.locator('#format').selectOption(settings.format);
    if (settings.every) {
      await page.locator('input[name="sp-mode"][value="every"]').check();
      await page.locator('#sp-unit').selectOption(settings.every.unit === 'seconds' ? '1' : '60');
      await page.locator('#sp-every').fill(String(settings.every.n));
    } else if (settings.times !== undefined) {
      await page.locator('#sp-times').fill(settings.times);
    }
    const blocked = await page.locator('#run').isDisabled();
    if ((await page.locator('#error.is-active').count()) === 0 && blocked) {
      return { state: 'blocked', message: (await page.locator('#run-hint, .run-hint, #hint').first().textContent().catch(() => '')) ?? (await page.locator('#sp-info').innerText()), names: [], sizes: [], ms: Date.now() - started };
    }
    let peakRss = 0;
    let peakHeap = 0;
    let stop = false;
    const sampler = opts.measure
      ? (async () => {
          while (!stop) {
            const m = await memory(page, browser);
            if (m) [peakRss, peakHeap] = [Math.max(peakRss, m.rss), Math.max(peakHeap, m.heap)];
            await page.waitForTimeout(250);
          }
        })()
      : Promise.resolve();
    // A file that failed to read already shows the error; pressing Run is then a second attempt at the same read, which is what a visitor would do.
    if (!(await page.locator('#run').isDisabled())) await page.locator('#run').click();
    await expect(page.locator('#results.is-active, #error.is-active').first()).toBeVisible({ timeout: 1_500_000 });
    stop = true;
    await sampler;
    const ms = Date.now() - started;
    const base = { ms, peakRssMb: opts.measure ? Math.round(peakRss) : undefined, peakHeapMb: opts.measure ? Math.round(peakHeap) : undefined };
    if ((await page.locator('#error.is-active').count()) > 0) {
      const ev = (await events(page)).filter((e) => e.n === 'tool_run' && e.d.outcome === 'error').at(-1);
      return { state: 'error', cls: ev?.d.error_class, message: await page.locator('#error').innerText(), names: [], sizes: [], ...base };
    }
    const names: string[] = [];
    const sizes: number[] = [];
    if (await page.locator('#download-all').isVisible()) {
      const [zip] = await Promise.all([page.waitForEvent('download'), page.locator('#download-all').click()]);
      const files = unzipSync(new Uint8Array(readFileSync((await zip.path())!)));
      for (const n of Object.keys(files).sort()) (names.push(n), sizes.push(files[n]!.length));
    } else {
      names.push(await page.locator('#results-list a[download], #results a[download]').first().getAttribute('download').then((x) => x ?? ''));
    }
    return { state: 'ok', message: '', names, sizes, ...base };
  } finally {
    await close();
  }
}

function record(name: string, o: Outcome) {
  if (process.env.AS_RECORD) appendFileSync(process.env.AS_RECORD, JSON.stringify({ name, ...o }) + '\n');
}

/** The seconds of sound in a 16-bit PCM WAV's header. */
const wavSeconds = (bytes: number, rate: number, channels: number) => (bytes - 44) / (rate * channels * 2);

test.beforeAll(() => {
  test.setTimeout(900_000);
  if (!existsSync(script)) throw new Error('fixture script missing');
  execFileSync('bash', [script, dir, 'small'], { stdio: 'inherit' });
});

// ---- Files in odd formats: each splits at 20 s and 40 s into three WAV parts of the right total length ----
const FORMATS: { file: string; rate: number; channels: number }[] = [
  { file: 'song-60s.mp3', rate: 44100, channels: 2 },
  { file: 'aac-60s.m4a', rate: 44100, channels: 2 },
  { file: 'opus-60s.webm', rate: 44100, channels: 2 },
  { file: 'opus-60s.ogg', rate: 44100, channels: 2 },
  { file: 'flac-60s.flac', rate: 44100, channels: 2 },
  { file: 'six-channel-60s.wav', rate: 44100, channels: 2 },
  { file: 'mono-8k-60s.wav', rate: 44100, channels: 1 },
  { file: 'hires-96k-60s.wav', rate: 44100, channels: 2 },
  { file: 'video-with-audio.mp4', rate: 44100, channels: 2 },
];
const NO_CI_DECODER = new Set(['aac-60s.m4a', 'opus-60s.webm', 'opus-60s.ogg', 'video-with-audio.mp4']);
for (const f of FORMATS) {
  test(`splits ${f.file} into three WAV parts`, async ({ browser }) => {
    test.setTimeout(240_000);
    const o = await splitFile(browser, fx(f.file), { times: '20, 0:40', format: 'wav' });
    record(f.file, o);
    // The browsers in CI (Linux) lack some decoders (AAC in Chromium, Opus and AAC in WebKit): there the file ends with the named class for it.
    if (process.env.CI && o.state === 'error' && NO_CI_DECODER.has(f.file)) return expect(o.cls).toBe('AudioDecodeError');
    expect(o, o.message).toMatchObject({ state: 'ok' });
    expect(o.names).toHaveLength(3);
    const total = o.sizes.reduce((n, b) => n + wavSeconds(b, f.rate, f.channels), 0);
    // The AAC and MP3 decoders add or drop a frame or two at the ends.
    expect(Math.abs(total - 60)).toBeLessThan(0.3);
    expect(Math.abs(wavSeconds(o.sizes[0]!, f.rate, f.channels) - 20)).toBeLessThan(0.05);
    expect(Math.abs(wavSeconds(o.sizes[1]!, f.rate, f.channels) - 20)).toBeLessThan(0.05);
  });
}

test('splits an MP3 into MP3 parts', async ({ browser }) => {
  const o = await splitFile(browser, fx('song-60s.mp3'), { times: '30', format: 'mp3' });
  record('song-60s.mp3 as mp3', o);
  expect(o, o.message).toMatchObject({ state: 'ok' });
  expect(o.names).toEqual(['song-60s-part-1.mp3', 'song-60s-part-2.mp3']);
});

// ---- Files that cannot be split: a named class for the real cause ----
const REFUSED: { file: string; what: string; cls: RegExp }[] = [
  { file: 'text-renamed.mp3', what: 'a text file renamed .mp3', cls: /^(AudioDecodeError|UnreadableFile)$/ },
];
for (const r of REFUSED) {
  test(`${r.what} ends with a named class`, async ({ browser }) => {
    test.setTimeout(240_000);
    const o = await splitFile(browser, fx(r.file), { times: '20' });
    record(r.file, o);
    expect(o.state).toBe('error');
    expect(o.cls).toMatch(r.cls);
    expect(o.message.length).toBeGreaterThan(20);
  });
}

test('a video with no sound track is refused when it is added, as NoSoundTrack, and is no run', async ({ browser }) => {
  const o = await splitFile(browser, fx('video-no-audio.mp4'), { times: '20' });
  record('video-no-audio.mp4', o);
  expect(o.state).toBe('blocked');
  expect(o.message).toContain('has no sound track');
});

test('a zero-length file is turned away when it is added, with the reason (no run is started)', async ({ browser }) => {
  const o = await splitFile(browser, fx('zero-length.mp3'), { times: '20' });
  record('zero-length.mp3', o);
  expect(o.state).toBe('error');
  expect(o.message).toMatch(/is empty/);
});

test('a truncated MP3 splits what is there, or ends with a named class', async ({ browser }) => {
  test.setTimeout(240_000);
  const o = await splitFile(browser, fx('truncated.mp3'), { times: '5', format: 'wav' });
  record('truncated.mp3', o);
  if (o.state === 'ok') expect(o.names.length).toBe(2);
  else expect(o.cls).toMatch(/^[A-Z][A-Za-z]+Error$|^NoSoundTrack$/);
});

test('a silent file splits into silent parts', async ({ browser }) => {
  const o = await splitFile(browser, fx('silent-60s.wav'), { times: '30', format: 'wav' });
  record('silent-60s.wav', o);
  expect(o, o.message).toMatchObject({ state: 'ok' });
  expect(o.names).toHaveLength(2);
});

test('an AMR voice memo and a 3GP voice memo split, or end with a named class', async ({ browser }) => {
  test.setTimeout(240_000);
  for (const f of ['voice-memo.amr', 'voice-memo.3gp']) {
    const o = await splitFile(browser, fx(f), { every: { n: 2, unit: 'seconds' }, format: 'wav' });
    record(f, o);
    if (o.state !== 'ok') expect(o.cls, f).toMatch(/^(AudioDecodeError|UnsupportedAudioCodec|NoSoundTrack|AudioDecodeFailed)$/);
    else expect(o.names.length).toBeGreaterThan(1);
  }
});

// ---- Split points that cannot be used: Run stays off, with the reason on the page; no run is started ----
const BAD_TIMES: { name: string; times?: string; every?: number; reason: RegExp }[] = [
  { name: 'times past the end', times: '20, 5:00', reason: /not inside the file/ },
  { name: 'unsorted times', times: '40, 20', reason: /in order/ },
  { name: 'a repeated time', times: '20, 20', reason: /twice/ },
  { name: 'every 0', every: 0, reason: /greater than zero/ },
  { name: 'text that is not a time', times: 'half way', reason: /is not a time/ },
];
for (const b of BAD_TIMES) {
  test(`${b.name}: Run is off and the page says why`, async ({ browser }) => {
    const o = await splitFile(browser, fx('song-60s.mp3'), b.every !== undefined ? { every: { n: b.every, unit: 'minutes' } } : { times: b.times });
    record(`bad times: ${b.name}`, o);
    expect(o.state).toBe('blocked');
    expect(o.message).toMatch(b.reason);
  });
}

test('1:02:03 is read as one hour, two minutes and three seconds', async ({ browser }) => {
  const { page, close } = await open(browser);
  try {
    await page.locator('#file-input').setInputFiles(fx('song-60s.mp3'));
    await expect(page.locator('#sp-info')).toContainText('long');
    await page.locator('#sp-times').fill('1:02:03');
    // Past the end of a minute-long file, but read as a time: the message names the time, not "not a time".
    await expect(page.locator('#sp-info')).toContainText('1:02:03 is not inside the file');
  } finally {
    await close();
  }
});

// ---- The sound encoder (LAME WebAssembly) failing to load, and failing part-way ----
const lameBlock = (times: number) => async (page: Page) => {
  let seen = 0;
  await page.route('**/vendor/wasm-media-encoders*/**', (route) => (seen++ < times ? route.abort('connectionreset') : route.continue()));
};
test('the MP3 encoder fails to load once: the run retries and succeeds', async ({ browser }) => {
  const o = await splitFile(browser, fx('song-60s.mp3'), { times: '30', format: 'mp3' }, { breakOn: lameBlock(1) });
  record('lame blocked once', o);
  expect(o, o.message).toMatchObject({ state: 'ok' });
  expect(o.names).toHaveLength(2);
});
test('the MP3 encoder never loads: a named class that says to choose WAV', async ({ browser }) => {
  const o = await splitFile(browser, fx('song-60s.mp3'), { times: '30', format: 'mp3' }, { breakOn: lameBlock(1e6) });
  record('lame blocked always', o);
  expect(o.state).toBe('error');
  expect(o.cls).toBe('Mp3EncoderLoadFailed');
  expect(o.message).toMatch(/WAV/);
});
test('the encoder failing part-way through a part ends with AudioSplitFailed', async ({ browser }) => {
  const o = await splitFile(browser, fx('song-60s.mp3'), { times: '30', format: 'mp3' }, {
    breakOn: async (page) => {
      await page.addInitScript(() => {
        // The fourth call into the WebAssembly encoder (enc_encode) throws, as it does when the encoder's own memory runs out.
        let calls = 0;
        const wrap = (r: unknown) => {
          const instance = ((r as { instance?: WebAssembly.Instance }).instance ?? r) as WebAssembly.Instance;
          const real = instance.exports.enc_encode as (...x: unknown[]) => unknown;
          // The exports object is frozen, so the encoder is handed a copy with enc_encode swapped.
          const exports = {
            ...instance.exports,
            enc_encode: (...x: unknown[]) => {
              if (++calls > 3) throw new WebAssembly.RuntimeError('unreachable executed');
              return real(...x);
            },
          };
          return r instanceof WebAssembly.Instance ? { exports } : { ...(r as object), instance: { exports } };
        };
        const inst = WebAssembly.instantiate.bind(WebAssembly) as (...a: unknown[]) => Promise<unknown>;
        WebAssembly.instantiate = ((...a: unknown[]) => inst(...a).then(wrap)) as typeof WebAssembly.instantiate;
        const stream = WebAssembly.instantiateStreaming.bind(WebAssembly) as (...a: unknown[]) => Promise<unknown>;
        WebAssembly.instantiateStreaming = ((...a: unknown[]) => stream(...a).then(wrap)) as typeof WebAssembly.instantiateStreaming;
      });
    },
  });
  record('encoder fails mid-part', o);
  expect(o.state).toBe('error');
  expect(o.cls).toBe('Mp3EncodeFailed');
});

// ---- Long recordings ----
test.describe('long recordings', () => {
  // Linux WebKit in CI has no sound decoder the page can stream from, so a long file there is decoded whole on a small runner: Chromium and the Mac's WebKit cover it.
  test.skip(({ browserName }) => browserName === 'webkit' && !!process.env.CI, 'no streaming decoder in Linux WebKit');
  test.beforeAll(() => {
    test.setTimeout(1_200_000);
    execFileSync('bash', [script, dir, 'all'], { stdio: 'inherit' });
  });

  test('a 2-hour stereo MP3 split every 10 minutes', async ({ browser }) => {
    test.setTimeout(2_400_000);
    const o = await splitFile(browser, fx('long-2h.mp3'), { every: { n: 10, unit: 'minutes' }, format: 'mp3' }, { measure: true });
    record('long-2h.mp3 every 10 min', o);
    expect(o, o.message).toMatchObject({ state: 'ok' });
    expect(o.names).toHaveLength(12);
    // 192 kbps constant bit rate: seconds = bytes * 8 / 192000.
    const seconds = o.sizes.reduce((n, b) => n + (b * 8) / 192_000, 0);
    expect(Math.abs(seconds - 7200)).toBeLessThan(30);
    if (o.peakRssMb !== undefined) expect(o.peakRssMb).toBeLessThan(1800);
  });

  test('a 3-hour recording on a phone browser (the stretch path)', async ({ browser }) => {
    test.setTimeout(2_400_000);
    const o = await splitFile(browser, fx('long-3h.mp3'), { every: { n: 30, unit: 'minutes' }, format: 'mp3' }, { userAgent: PHONE, measure: true });
    record('long-3h.mp3 phone every 30 min', o);
    // On a phone the page either splits it or says plainly that this device ran out of memory.
    if (o.state === 'ok') expect(o.names).toHaveLength(6);
    else expect(o.cls).toBe('OutOfMemoryError');
  });
});
